examples.template:
MonarchSwitchSettingsList({{title}}, description: {{description}}) {
    MonarchSwitchSettingsRow({{items.0.label}}, isOn: $alerts, description: {{items.0.description}}) { _ in
        try await Task.sleep(for: .milliseconds({{saveMillis}}))
    }
    MonarchSwitchSettingsRow({{items.1.label}}, isOn: $devices, description: {{items.1.description}}) { _ in
        try await Task.sleep(for: .milliseconds({{saveMillis}}))
    }
    MonarchSwitchSettingsRow({{items.2.label}}, isOn: $digest) { _ in
        try await Task.sleep(for: .milliseconds({{saveMillis}}))
    }
}

examples.setupTemplate:
@State private var alerts = {{items.0.checked}}
@State private var devices = {{items.1.checked}}
@State private var digest = {{items.2.checked}}

examples.setup:
@State private var alerts = true
@State private var devices = true
@State private var digest = false

examples.code:
MonarchSwitchSettingsList("Security notifications", description: "Emails about activity on your account.") {
    MonarchSwitchSettingsRow("Security alerts", isOn: $alerts, description: "Password changes and new recovery methods.") { _ in
        try await Task.sleep(for: .milliseconds(700))
    }
    MonarchSwitchSettingsRow("New device sign-in", isOn: $devices, description: "When your account is used on a device for the first time.") { _ in
        try await Task.sleep(for: .milliseconds(700))
    }
    MonarchSwitchSettingsRow("Weekly summary", isOn: $digest) { _ in
        try await Task.sleep(for: .milliseconds(700))
    }
}

MonarchSwitchSettingsList("Privacy") {
    MonarchSwitchSettingsRow(
        "Share usage data",
        isOn: $shareData,
        onStatusChange: { status = $0 },
        save: { _ in try await Task.sleep(for: .milliseconds(300)) }
    )
}
MonarchButton("Done", variant: .primary) {}
    .disabled(status == .saving)
